local b64 = ""
local isWin = package.config:sub(1,1) == '\\'
local isMac = not isWin and (io.popen("uname -s 2>/dev/null"):read("*l") or ""):find("Darwin") ~= nil
local sep = isWin and '\\' or '/'
local tempDir = os.getenv("TEMP") or os.getenv("TMPDIR") or (isWin and "C:\\temp" or "/tmp")
local pyScript = tempDir .. sep .. "AutoCapStyle_Core.py"

local pyWrapper = "import base64; exec(base64.b64decode('" .. b64 .. "').decode('utf-8'))\n"
local f = io.open(pyScript, "w")
if f then
    f:write(pyWrapper)
    f:close()
end

local function findPython()
    local candidates = {}
    if isWin then
        local localApp = os.getenv("LOCALAPPDATA") or ""
        local progFiles = os.getenv("ProgramFiles") or "C:\\Program Files"
        local winDir = os.getenv("WINDIR") or "C:\\Windows"
        candidates = {
            progFiles .. "\\Python311\\python.exe",
            progFiles .. "\\Python311\\pythonw.exe",
            localApp .. "\\Programs\\Python\\Python311\\python.exe",
            localApp .. "\\Programs\\Python\\Python311\\pythonw.exe",
            progFiles .. "\\Python312\\python.exe",
            progFiles .. "\\Python312\\pythonw.exe",
            localApp .. "\\Programs\\Python\\Python312\\python.exe",
            localApp .. "\\Programs\\Python\\Python312\\pythonw.exe",
            progFiles .. "\\Python310\\python.exe",
            progFiles .. "\\Python310\\pythonw.exe",
            localApp .. "\\Programs\\Python\\Python310\\python.exe",
            localApp .. "\\Programs\\Python\\Python310\\pythonw.exe",
            "C:\\Python311\\python.exe",
            "C:\\Python312\\python.exe",
            "C:\\Python310\\python.exe",
            winDir .. "\\py.exe",
            "pythonw",
            "python"
        }
    elseif isMac then
        local home = os.getenv("HOME") or ""
        candidates = {
            "/Library/Frameworks/Python.framework/Versions/3.11/bin/python3",
            "/Library/Frameworks/Python.framework/Versions/3.12/bin/python3",
            "/Library/Frameworks/Python.framework/Versions/3.10/bin/python3",
            "/opt/homebrew/bin/python3.11",
            "/opt/homebrew/bin/python3.12",
            "/opt/homebrew/bin/python3.10",
            "/usr/local/bin/python3.11",
            "/usr/local/bin/python3.12",
            "/usr/local/bin/python3.10",
            "/opt/homebrew/bin/python3",
            "/usr/local/bin/python3",
            home .. "/Library/Python/3.11/bin/python3",
            home .. "/Library/Python/3.12/bin/python3",
            "/usr/bin/python3",
            "python3"
        }
    else
        candidates = {
            "/usr/bin/python3.11",
            "/usr/local/bin/python3.11",
            "/usr/bin/python3.12",
            "/usr/local/bin/python3.12",
            "/usr/bin/python3",
            "/usr/local/bin/python3",
            "python3"
        }
    end

    for _, c in ipairs(candidates) do
        local testCmd = ""
        if isWin then
            if c:find("\\") then
                testCmd = '"' .. c .. '" -c "import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)" >nul 2>&1'
            else
                testCmd = c .. ' -c "import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)" >nul 2>&1'
            end
        else
            testCmd = '"' .. c .. '" -c "import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)" >/dev/null 2>&1'
        end

        local res = os.execute(testCmd)
        if res == 0 or res == true then
            return c
        end
    end
    return nil
end

local pyExec = findPython()

if not pyExec then
    local ui = fu.UIManager
    local disp = bmd.UIDispatcher(ui)
    local win = disp:AddWindow({
        ID = "PythonReqWin",
        WindowTitle = "Auto Cap's Style v1.0.0 - Setup Required",
        Geometry = { 400, 250, 480, 260 },
        Margin = 0,
        StyleSheet = [[
            QWidget {
                background-color: #18181c;
                color: #e5e7eb;
                font-family: -apple-system, 'Segoe UI', Roboto, sans-serif;
            }
            QPushButton {
                background-color: #2b2b34;
                color: #ffffff;
                border: 1px solid #3e3e4a;
                border-radius: 6px;
                padding: 6px 14px;
                font-weight: bold;
                font-size: 12px;
                min-height: 28px;
            }
            QPushButton:hover {
                background-color: #383844;
                border-color: #555566;
            }
            QPushButton#DownloadBtn {
                background-color: #2563eb;
                border: 1px solid #1d4ed8;
                min-width: 140px;
            }
            QPushButton#DownloadBtn:hover {
                background-color: #3b82f6;
                border-color: #2563eb;
            }
            QPushButton#CloseBtn {
                min-width: 100px;
            }
        ]],
        ui:VGroup{
            ID = "RootLayout",
            Margin = 24,
            Spacing = 16,
            ui:Label{
                ID = "HeaderLabel",
                Text = "<html><table width='100%' cellpadding='0' cellspacing='0'><tr><td><div style='font-size: 18px; font-weight: bold; color: #ffffff;'>Python 3.11 Required</div><div style='font-size: 13px; color: #9ca3af; margin-top: 4px;'>Auto Cap's Style requires Python 3.11 to integrate with DaVinci Resolve</div></td><td align='right' valign='top'><span style='background-color: #3b1f14; color: #f97316; border: 1px solid #7c2d12; border-radius: 4px; padding: 4px 8px; font-size: 10px; font-weight: bold;'>SETUP REQUIRED</span></td></tr></table></html>",
                Weight = 0,
            },
            ui:Label{
                ID = "CardLabel",
                Text = "<html><div style='background-color: #222228; border: 1px solid #2e2e38; border-radius: 6px; padding: 16px;'><table cellpadding='6' cellspacing='0' width='100%'><tr><td width='26' valign='top' style='color: #60a5fa; font-weight: bold; font-size: 14px;'>1.</td><td style='color: #e5e7eb; font-size: 13px; line-height: 1.4;'>Click <b>Download Python 3.11</b> below to open the official Python installer.</td></tr><tr><td width='26' valign='top' style='color: #f59e0b; font-weight: bold; font-size: 14px;'>2.</td><td style='color: #fde68a; font-size: 13px; line-height: 1.4;'><b>IMPORTANT:</b> Complete installation with PATH enabled.</td></tr><tr><td width='26' valign='top' style='color: #60a5fa; font-weight: bold; font-size: 14px;'>3.</td><td style='color: #e5e7eb; font-size: 13px; line-height: 1.4;'>Once installation finishes, re-run this plugin from <b>Workspace &gt; Scripts</b>.</td></tr></table></div></html>",
                Weight = 0,
            },
            ui:VGap(15),
            ui:HGroup{
                ID = "FooterButtons",
                Spacing = 12,
                ui:HGap(1),
                ui:Button{
                    ID = "CloseBtn",
                    Text = "Cancel",
                },
                ui:Button{
                    ID = "DownloadBtn",
                    Text = "Download Python 3.11",
                },
            },
        }
    })

    win.On.PythonReqWin.Close = function(ev) disp:ExitLoop() end
    win.On.CloseBtn.Clicked = function(ev) disp:ExitLoop() end
    win.On.DownloadBtn.Clicked = function(ev)
        local dlUrl = isWin and 'https://www.python.org/ftp/python/3.11.9/python-3.11.9-amd64.exe'
                             or (isMac and 'https://www.python.org/ftp/python/3.11.9/python-3.11.9-macos11.pkg' or 'https://www.python.org/downloads/')
        if isWin then
            os.execute('start ' .. dlUrl)
        elseif isMac then
            os.execute('open ' .. dlUrl)
        else
            os.execute('xdg-open ' .. dlUrl)
        end
        disp:ExitLoop()
    end

    win:Show()
    disp:RunLoop()
    win:Hide()
else
    if isWin then
        if pyExec:find("\\") then
            os.execute('start "" "' .. pyExec .. '" "' .. pyScript .. '"')
        else
            os.execute('start "" ' .. pyExec .. ' "' .. pyScript .. '"')
        end
    else
        os.execute('"' .. pyExec .. '" "' .. pyScript .. '" &')
    end
end
